def calculate_n(a, b, c):
    """Calculates the value of n for a given triple (a, b, c)."""
    if a <= 0 or b <= 0 or c <= 0 or a == b or b == c or a == c:
        return None

    S = a + b + c
    Q = a * b + b * c + c * a

    # Numerator: (a+b+c)(ab+bc+ca) + a+b+c = S * Q + S = S * (Q + 1)
    Numerator = S * (Q + 1)

    # Denominator: 4abc
    Denominator = 4 * a * b * c

    if Denominator == 0:
        return None # Should not happen with positive integers

    # Check if n is an integer
    if Numerator % Denominator == 0:
        return Numerator // Denominator
    else:
        return None

