def calculate_n(a, b, c):
    # a, b, c are distinct positive integers
    S = a + b + c
    Q = ab + bc + ca
    numerator = S * (Q + 1)
    denominator = 4 * a * b * c

    if denominator == 0:
        return None # Should not happen with positive integers

    return numerator / denominator

def check_n_equals_target(a, b, c, target_n):
    n_val = calculate_n(a, b, c)
    if n_val is None:
        return False
    # Check if n_val is an integer and equals the target
    return abs(n_val - target_n) < 1e-9

